{
  "region": "Cardinality: 30 (30 regions across 4 countries). Filter usage: C5 (per-region grid balance, 30/day at 30-min SLA)",
  "customer_id": "Cardinality: 12M. Filter usage: C6 (churn analytics, 100/day) and C8 (ML features, 1/day on 50K customer_ids)",
  "substation_id": "Cardinality: 600. Filter usage: C9 (anomaly detection, 1/hour on substation_id IN list)",
  "reading_ts": "Cardinality: continuous (timestamp). Filter usage: C9 (1-hour windows on reading_ts)"
}

{
  "z_order": "Requires explicit OPTIMIZE; clustering columns fixed at table-create or via column-list at each OPTIMIZE; rewrite cost ~30 min per night for 8 TB",
  "liquid_clustering": "Automatic, runs incrementally on writes; clustering keys can be changed without a full rewrite; no separate OPTIMIZE budget needed"
}

{
  "spark_version": "3.4",
  "join_order": "readings × customer_profile × tariffs × substations × audit_periods",
  "join_3_strategy": "BroadcastHashJoin on tariffs (post-AQE; tariffs filtered to active rows came in at 8 MB)",
  "runtime": "105 min"
}

{
  "spark_version": "3.5",
  "join_order_change": "Spark 3.5's optimizer reordered join 3 (tariffs) to position 5 (after substations and audit_periods), putting it after a join that inflates the left side 4x",
  "join_5_strategy": "SortMergeJoin on tariffs (the inflated left side made the broadcast collection more expensive than sort-merge under the new planner heuristic)",
  "runtime": "220 min, with 4 TB shuffle on join 5 that did not exist in the 3.4 plan"
}

{
  "H1_stale_to_fresh_statistics_changed_join_order": "ANALYZE on customer_profile changed the join order. A different join order produces a different aggregation traversal, which when combined with floating-point summation can produce different totals due to non-associativity of float addition.",
  "H2_AQE_skew_split_altered_output_ordering": "Tighter AQE skew-split produces partial aggregates that, when combined at the final aggregation, sum in different orders each run. Same floating-point non-associativity, but produces non-reproducible results across runs.",
  "H3_partition_migration_changed_file_count": "More partitions = more partial aggregates merged at the end. Different file count could change the merge order at the final stage."
}
